        # Returns tuple for stable sorting
        major, minor, patch, prerelease_ids = parse_version(v)

        # For pre-release comparison, we need a sortable key
        # We'll use a tuple where:
        # - (major, minor, patch) for base version
        # - prerelease sorting key

        if prerelease_ids is None:
            # No pre-release: sorts after any pre-release of same version
